#include <bamseek/evidence.hpp>
#include <bamseek/query.hpp>
#include <bamseek/comparison.hpp>
#include <iostream>
#include <sstream>
int main(int argc,char**argv){if(argc<2)return 2;std::ostringstream text;text<<std::cin.rdbuf();auto parsed=bamseek::parse_queries(text.str());if(!parsed.errors.empty())return 3;bamseek::EvidenceEngine engine({.uri=argv[1]});bamseek::FilterSettings s;if(argc>2){s.molecule_mode=bamseek::MoleculeMode::selected_tag;s.molecule_tag=argv[2];}auto batch=engine.evaluate(parsed.queries,s);if(!batch.errors.empty())return 4;for(const auto&r:batch.results){auto&e=std::get<bamseek::VariantEvidence>(r);auto&c=e.counts;std::cout<<"v\t"<<c.reference_reads<<'\t'<<c.alternate_reads<<'\t'<<c.other_reads<<'\t'<<c.reference_molecules<<'\t'<<c.alternate_molecules<<'\t'<<c.other_molecules<<'\t'<<e.filtered_alignments<<'\t'<<e.uncallable_alignments<<'\t'<<e.low_base_quality_alignments<<'\t'<<e.reads_missing_molecule_tag<<'\n';}std::vector<bamseek::VariantQuery> vs;for(auto&q:parsed.queries)vs.push_back(std::get<bamseek::VariantQuery>(q));if(vs.size()==2){auto p=engine.phase_pair(vs[0],vs[1],s);std::cout<<"p\t"<<bamseek::phase_name(p.classification)<<'\t'<<p.counts.alternate_alternate<<'\t'<<p.counts.alternate_reference<<'\t'<<p.counts.reference_alternate<<'\t'<<p.counts.reference_reference<<'\n';auto ls=engine.dev_local_phase(vs,s);if(!ls.empty()){auto&l=ls[0];std::cout<<"l\t"<<bamseek::dev_local_phase_name(l.classification)<<'\t'<<l.discovered_snps<<'\t'<<l.common_snps<<'\t'<<l.supporting_chains<<'\n';}}return 0;}
